# Check the found graph for cycles
edges = [(0, 2), (0, 7), (0, 12), (0, 14), (1, 6), (1, 18), (2, 17), (3, 4), (3, 9), (3, 14), (4, 8), (4, 17), (5, 12), (5, 15), (6, 14), (6, 15), (6, 16), (7, 8), (8, 13), (8, 15), (9, 18), (10, 12), (10, 16), (11, 17), (11, 18), (12, 18), (13, 18), (16, 17)]

# Build adjacency
adj = {i: set() for i in range(19)}
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

# Check for cycles using BFS up to length 6
def find_cycle_length(start):
    # BFS to find shortest cycle containing start
    # Use (node, parent, depth)
    from collections import deque
    visited = {}
    q = deque()
    q.append((start, -1, 0))
    visited[start] = (-1, 0)

    min_cycle = float('inf')
    while q:
        node, parent, depth = q.popleft()
        if depth >= 4:  # No need to go deeper than half of max cycle length
            continue
        for nb in adj[node]:
            if nb == parent:
                continue
            if nb in visited:
                # Found cycle
                cycle_len = depth + 1 + visited[nb][1]
                if cycle_len < min_cycle:
                    min_cycle = cycle_len
            else:
                visited[nb] = (node, depth+1)
                q.append((nb, node, depth+1))
    return min_cycle

girth = float('inf')
for v in range(19):
    cl = find_cycle_length(v)
    if cl < girth:
        girth = cl
print(f"Girth: {girth}")

# Also verify coloring
colors = [1, 0, 2, 2, 0, 0, 1, 0, 1, 0, 1, 2, 2, 2, 0, 2, 2, 1, 1]
for u,v in edges:
    if colors[u] == colors[v]:
        print(f"Color conflict: {u}-{v}")
        break
else:
    print("Coloring valid")

import z3
import time

n = 19
min_edges = 28

edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[(i,j)] = z3.Bool(f"e_{i}_{j}")

def edge_var(i, j):
    if i < j:
        return edges[(i,j)]
    else:
        return edges[(j,i)]

colors = [z3.Int(f"c_{i}") for i in range(n)]

s = z3.Solver()

for i in range(n):
    s.add(colors[i] >= 0, colors[i] <= 2)

for (i,j), e in edges.items():
    s.add(z3.Implies(e, colors[i] != colors[j]))

print("Adding cycle constraints...")

# 3-cycles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            s.add(z3.Not(z3.And(edge_var(i,j), edge_var(i,k), edge_var(j,k))))
print("Added 3-cycle constraints")

# 4-cycles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                s.add(z3.Not(z3.And(edge_var(i,j), edge_var(j,k), edge_var(k,l), edge_var(i,l))))
                s.add(z3.Not(z3.And(edge_var(i,j), edge_var(j,l), edge_var(k,l), edge_var(i,k))))
                s.add(z3.Not(z3.And(edge_var(i,k), edge_var(j,k), edge_var(j,l), edge_var(i,l))))
print("Added 4-cycle constraints")

# 5-cycles
import itertools
count5 = 0
for combo in itertools.combinations(range(n), 5):
    verts = list(combo)
    first = verts[0]
    for perm in itertools.permutations(verts[1:]):
        cycle = [first] + list(perm)
        if cycle[1] < cycle[4]:
            e1 = edge_var(cycle[0], cycle[1])
            e2 = edge_var(cycle[1], cycle[2])
            e3 = edge_var(cycle[2], cycle[3])
            e4 = edge_var(cycle[3], cycle[4])
            e5 = edge_var(cycle[4], cycle[0])
            s.add(z3.Not(z3.And(e1, e2, e3, e4, e5)))
            count5 += 1
print(f"Added 5-cycle constraints: {count5}")

# Edge count constraint
edge_count = z3.Sum([z3.If(e, 1, 0) for e in edges.values()])
s.add(edge_count >= min_edges)

print(f"Starting solve with min_edges={min_edges}...")
start = time.time()
result = s.check()
print(f"Result: {result}, time: {time.time() - start:.2f}s")

if result == z3.sat:
    model = s.model()
    edge_list = []
    for (i,j), e in edges.items():
        if z3.is_true(model.evaluate(e)):
            edge_list.append((i,j))
    print(f"Found {len(edge_list)} edges")

    # Check for 6-cycles
    adj = {i: set() for i in range(n)}
    for u,v in edge_list:
        adj[u].add(v)
        adj[v].add(u)

    # BFS-based cycle detection
    from collections import deque
    six_cycles_found = False
    for start in range(n):
        visited = {}
        q = deque()
        q.append((start, -1, 0))
        visited[start] = (0, -1)
        while q:
            node, parent, depth = q.popleft()
            if depth >= 3:
                continue
            for nb in adj[node]:
                if nb == parent:
                    continue
                if nb not in visited:
                    visited[nb] = (depth+1, node)
                    q.append((nb, node, depth+1))
                else:
                    # Found a cycle. Compute length.
                    # We need to find the actual cycle length
                    # Let's do path reconstruction
                    cycle_len = depth + 1 + visited[nb][0]
                    if cycle_len == 6:
                        six_cycles_found = True
                        break
            if six_cycles_found:
                break
        if six_cycles_found:
            break

    if six_cycles_found:
        print("WARNING: 6-cycle found!")
    else:
        print("No 6-cycles found")

    color_vals = [model.evaluate(colors[i]).as_long() for i in range(n)]
    print("Colors:", color_vals)
    print("Edges:", edge_list)
else:
    print("UNSAT")
